/**
 * @method
 * @name scwin.dataValidation
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dataValidation = async function () {
    /* sdd-asis-lifecycle:begin dataValidation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const nullInput = $("table[name=conTable] input:visible[name!=''][type='text'][value='']");
    for (let i = 0; i < nullInput.length; i++) {
        if ($c.str.getByteLength($($(nullInput)[i]).val()) == 0) {
            const ipNm = $($(nullInput)[i]).attr("name");
            if ($($(nullInput)[i]).attr("id") === "nusualIsuCondContn") {
                continue;
            }
            const labelNm = $('[for="' + ipNm + '"]').text();
            await $c.win.alert(labelNm + "을(를) 입력하세요.");
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return true;
        }
    }
    const old_isu_dd = $c.util.getComponent('ipt_oldIsuDd').getValue();
    const isu_dd = $c.util.getComponent('cal_isuDd').getValue();
    if (old_isu_dd.substring(0, 4) !== isu_dd.substring(0, 4)) {
        await $c.win.alert("발행일의 년도는 수정할 수 없습니다.");
        ($c.util.getComponent('cal_isuDd') && $c.util.getComponent('cal_isuDd').setFocus ? $c.util.getComponent('cal_isuDd').setFocus() : ($c.util.getComponent('cal_isuDd') && $c.util.getComponent('cal_isuDd').focus ? $c.util.getComponent('cal_isuDd').focus() : console.warn('[sdd] focus 대상 미해결: cal_isuDd')));
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_nusualIsuCondContn').getValue()) > 0) {
        if ($c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\t") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\n") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\r") > -1) {
            await $c.win.alert("특이발행조건에 '탭문자' 혹은 '개행문자'가 포함되어있습니다.\n다시 입력해 주십시오.");
            $("#ipt_nusualIsuCondContn").select();
            return true;
        }
    }
    if (!await scwin.chk_mod_text($c.util.getComponent('ipt_delRsn').getValue())) {
        $c.util.getComponent("ipt_delRsn").focus();
        return true;
    }
    if (!$('input[name=group]').is(":checked")) {
        await $c.win.alert("'그룹'을 선택하세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr01').getValue()) == 0) {
        await $c.win.alert("'1차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr01").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr02').getValue()) == 0) {
        await $c.win.alert("'2차속성'을 선택하세요.");
        $c.util.getComponent("slc_attr02").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_attr03').getValue()) == 0) {
        await $c.win.alert("'3차속성'을 선택하세요.");
